        Notes = r.IsDBNull(5) ? null : r.GetString(5),
        Pdf = r.IsDBNull(6) ? null : r.GetFieldValue<byte[]>(6),
        DueIn = r.IsDBNull(7) ? null : r.GetFieldValue<TimeSpan>(7),
    };

    private async ValueTask OpenAsync(CancellationToken ct)
    {
        if (db.State != ConnectionState.Open) await db.OpenAsync(ct);
    }

    public async Task<Invoice?> GetByIdAsync(long invoiceId, CancellationToken ct = default)
    {
