        cmd.CommandText = SelectByIdSql;
        cmd.BindByName = true;
        cmd.Parameters.Add(new OracleParameter("InvoiceId", invoiceId));
        await OpenAsync(ct);
        await using var reader = await cmd.ExecuteReaderAsync(ct);
        return await reader.ReadAsync(ct) ? Map(reader) : null;
    }

