        cmd.Parameters.Add(new OracleParameter("Paid", entity.Paid));
        cmd.Parameters.Add(new OracleParameter("Notes", (object?)entity.Notes ?? DBNull.Value));
        cmd.Parameters.Add(new OracleParameter("Pdf", (object?)entity.Pdf ?? DBNull.Value));
        cmd.Parameters.Add(new OracleParameter("DueIn", (object?)entity.DueIn ?? DBNull.Value));
        var id = new OracleParameter { ParameterName = "InvoiceId", OracleDbTypeEx = OracleDbType.Int64, Direction = ParameterDirection.Output };
        cmd.Parameters.Add(id);
        await OpenAsync(ct);
        await cmd.ExecuteNonQueryAsync(ct);
        return Convert.ToInt64(id.Value);
    }

    public async Task<bool> UpdateAsync(Invoice entity, CancellationToken ct = default)
    {
