public sealed class CustomerOrdersRow
{
    public decimal Id { get; set; }

    public string Name { get; set; } = "";

    public decimal Total { get; set; }

    public DateTime? OrderDate { get; set; }
}

public static class CustomerOrdersQuery
{
    public const string Sql = """
        SELECT c.ID, c.NAME, o.TOTAL, o.ORDER_DATE
        FROM SHOP.CUSTOMERS c
        JOIN SHOP.ORDERS o ON o.CUSTOMER_ID = c.ID
        WHERE c.ID = :customer_id AND o.TOTAL > :min_total
        ORDER BY o.ORDER_DATE DESC
        """;

    public static async Task<IReadOnlyList<CustomerOrdersRow>> GetCustomerOrdersAsync(this OracleConnection db, int customerId, decimal minTotal, CancellationToken ct = default)
    {
        await using var cmd = db.CreateCommand();
        cmd.CommandText = Sql;
        cmd.BindByName = true;
        cmd.Parameters.Add(new OracleParameter("customer_id", customerId));
        cmd.Parameters.Add(new OracleParameter("min_total", minTotal));
        if (db.State != ConnectionState.Open) await db.OpenAsync(ct);
        await using var r = await cmd.ExecuteReaderAsync(ct);
        var list = new List<CustomerOrdersRow>();
        while (await r.ReadAsync(ct))
        {
            list.Add(new CustomerOrdersRow
            {
                Id = r.GetDecimal(0),
                Name = r.GetString(1),
                Total = r.GetDecimal(2),
                OrderDate = r.IsDBNull(3) ? null : r.GetDateTime(3),
            });
        }
        return list;
    }
}

public sealed record GetCustomerOrdersResult(IReadOnlyList<dynamic> Orders);
