    /// <summary>Calls SHOP.NEXT_INVOICE_NO.</summary>
    public static async Task<NextInvoiceNoResult> NextInvoiceNoAsync(this OracleConnection db, string prefix, decimal? seq, CancellationToken ct = default)
    {
        await using var cmd = db.CreateCommand();
        cmd.BindByName = true;
        cmd.CommandText = "SHOP.NEXT_INVOICE_NO";
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.Parameters.Add("P_PREFIX", OracleDbType.Varchar2).Value = (object?)prefix ?? DBNull.Value;
        var seqParam = cmd.Parameters.Add(new OracleParameter { ParameterName = "P_SEQ", OracleDbTypeEx = OracleDbType.Decimal, Direction = ParameterDirection.InputOutput });
        seqParam.Value = (object?)seq ?? DBNull.Value;
        var numberParam = cmd.Parameters.Add(new OracleParameter { ParameterName = "P_NUMBER", OracleDbTypeEx = OracleDbType.Varchar2, Direction = ParameterDirection.Output, Size = 32767 });
        if (db.State != ConnectionState.Open) await db.OpenAsync(ct);
        await cmd.ExecuteNonQueryAsync(ct);
        return new NextInvoiceNoResult(numberParam.Value is null or DBNull ? (string?)null : Convert.ToString(numberParam.Value)!, seqParam.Value is null or DBNull ? (decimal?)null : Convert.ToDecimal(seqParam.Value));
    }

    private static dynamic ToExpando(IDataRecord r)
    {
        IDictionary<string, object?> row = new ExpandoObject();
        for (var i = 0; i < r.FieldCount; i++) row[r.GetName(i)] = r.IsDBNull(i) ? null : r.GetValue(i);
        return row;
    }
}

